// Group incomplete tasks by assignee; flag overdue and due-today.
const tasks = $input.all().map(i => i.json).filter(t => !t.completed);
const today = new Date().toISOString().slice(0,10);
const byAssignee = {}; const overdue = []; const dueToday = [];
for (const t of tasks) {
  const who = t.assignee?.name || 'Unassigned';
  (byAssignee[who] = byAssignee[who] || []).push(t.name);
  if (t.due_on && t.due_on < today) overdue.push(t.name);
  else if (t.due_on === today) dueToday.push(t.name);
}
const lines = Object.entries(byAssignee).map(([who, names]) => '**' + who + '** (' + names.length + '): ' + names.join(', '));
return [{ json: { total: tasks.length, overdue, dueToday, lines } }];

